-- step61: удаление тату лазером — английская версия 1625 (/en/laser-tattoo-removal, шаблон 19 «Категория NEW», старый дизайн с новыми
-- шапкой и подвалом, как RO 625 / RU 321); блок «Преимущества» (с lbar.com.ua) и третье оборудование (Face Lift 3 in 1) у RO / RU / EN;
-- старые чанки — под EN: окно консультации (текст по-английски), галерея и отзывы EN — RO-двойника (lb.roId).
-- Сгенерировано _dev/tools/en_tz.py (перевод — _dev/en/tr/625.json). Повторный запуск безопасен (EN-строки и TV пересоздаются).
-- Картинка третьего аппарата — файл /images/inner/eq-face-lift.webp (положить на хостинг).
SET NAMES utf8mb4;

-- RO / RU: блок «Преимущества» и список оборудования (третий аппарат)
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 282 AND contentid = 321;
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 283 AND contentid = 321;
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 284 AND contentid = 321;
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 282 AND contentid = 625;
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 283 AND contentid = 625;
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 284 AND contentid = 625;

DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE contentid = 1625;
DELETE FROM Impulse_Digital_X_site_content WHERE id = 1625 AND context_key = 'en';

UPDATE Impulse_Digital_X_site_tmplvar_contentvalues SET value = CONCAT(REPLACE(value, ';en:1625', ''), ';en:1625') WHERE tmplvarid = 304 AND contentid IN (625, 321);

-- подвал EN-главной (TV foot-link-l у 1001): + Laser tattoo removal
UPDATE Impulse_Digital_X_site_tmplvar_contentvalues SET value = REPLACE(value, '<p><a href="/en/laser-hair-removal">Laser hair removal</a></p>', '<p><a href="/en/laser-hair-removal">Laser hair removal</a></p>\n\n<p><a href="/en/laser-tattoo-removal">Laser tattoo removal</a></p>') WHERE tmplvarid = (SELECT id FROM Impulse_Digital_X_site_tmplvars WHERE name = 'foot-link-l') AND contentid = 1001 AND value NOT LIKE '%/en/laser-tattoo-removal%';

-- banner-interial-category-new: окно «Консультация» — третий язык (было: ro → RO, иначе RU)
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(REPLACE(snippet, '[[++cultureKey:is=`ro`:then=`Ia o consultație de la un specialist`:else=`Получить консультацию мастера`]]', '{if $_modx->config.cultureKey == \'ro\'}Ia o consultație de la un specialist{elseif $_modx->config.cultureKey == \'en\'}Get a consultation with a specialist{else}Получить консультацию мастера{/if}'), '[[++cultureKey:is=`ro`:then=`Aflați toate detaliile îndepărtării cu laser și obțineți răspunsuri la întrebările rămase de la specialistul dumneavoastră`:else=`Узнайте все детали лазерного удаления и получите ответы на оставшиеся вопросы от вашего мастера`]]', '{if $_modx->config.cultureKey == \'ro\'}Aflați toate detaliile îndepărtării cu laser și obțineți răspunsuri la întrebările rămase de la specialistul dumneavoastră{elseif $_modx->config.cultureKey == \'en\'}Find out all the details of laser removal and get answers to any remaining questions from your specialist{else}Узнайте все детали лазерного удаления и получите ответы на оставшиеся вопросы от вашего мастера{/if}') WHERE name = 'banner-interial-category-new';

-- bl6-portfolio-new: фото — ресурса lb.roId (у EN — RO-двойник; у RO / RU — сам ресурс, как было)
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(snippet, '{set $portfolio = $_modx->runSnippet(\'!ms2Gallery\', [\n', '{set $portfolio = $_modx->runSnippet(\'!ms2Gallery\', [\n\'resources\' => ($_modx->getChunk(\'lb.roId\') | trim),\n') WHERE name = 'bl6-portfolio-new' AND snippet NOT LIKE '%lb.roId%';

-- bl9-reviews-new: ветка отзывов — resource-<lb.roId> (у EN — RO-двойника; у RO / RU — своя, как было)
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(snippet, '{var $rateCount = \'!ecMessagesCount\' | snippet}', '{var $tid = $_modx->getChunk(\'lb.roId\') | trim}{var $rateCount = $_modx->runSnippet(\'!ecMessagesCount\', [\'thread\' => \'resource-\' ~ $tid])}'), '[[!ecMessagesCount]]', '[[!ecMessagesCount? &thread=`resource-{$tid}`]]'), '[[!ecThreadRating]]', '[[!ecThreadRating? &thread=`resource-{$tid}`]]'), '[[!ecMessages? &tpl=`tpl.ecMessages.Row`]]', '[[!ecMessages? &thread=`resource-{$tid}` &tpl=`tpl.ecMessages.Row`]]'), '[[!ecForm?\n', '[[!ecForm?\n                            &thread=`resource-{$tid}`\n') WHERE name = 'bl9-reviews-new' AND snippet NOT LIKE '%lb.roId%';

-- bl-contact (контакты старых страниц): на EN — адрес, трамвай и график по-английски (RO / RU — без изменений, как было)
UPDATE Impulse_Digital_X_site_htmlsnippets SET snippet = REPLACE(REPLACE(REPLACE(snippet, 'București, Sector 1', '{if $_modx->config.cultureKey == \'en\'}Bucharest, Sector 1{else}București, Sector 1{/if}'), 'Stația de tramvai Ștefan cel Mare', '{if $_modx->config.cultureKey == \'en\'}Ștefan cel Mare tram stop{else}Stația de tramvai Ștefan cel Mare{/if}'), 'Programa: <br/>Luni-Duminica 9:00 - 20:00', '{if $_modx->config.cultureKey == \'en\'}Opening hours: <br/>Monday – Sunday 9:00 - 20:00{else}Programa: <br/>Luni-Duminica 9:00 - 20:00{/if}') WHERE name = 'bl-contact' AND snippet NOT LIKE '%Bucharest, Sector 1%';

