INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (282, 625, 'Avantajele <span class=\"gold-word\">îndepărtării tatuajelor și machiajului permanent</span> cu laser');
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (283, 625, '[{\"MIGX_id\":\"1\",\"number\":\"01\",\"title\":\"\\u00cendep\\u0103rtare f\\u0103r\\u0103 arsuri, f\\u0103r\\u0103 cicatrici, f\\u0103r\\u0103 urme.\",\"text\":\"Dup\\u0103 vindecare, pielea este perfect curat\\u0103, f\\u0103r\\u0103 nicio urm\\u0103, complet preg\\u0103tit\\u0103 pentru o nou\\u0103 pigmentare, dac\\u0103 este nevoie.\"},{\"MIGX_id\":\"2\",\"number\":\"02\",\"title\":\"Sigur pentru pielea de orice v\\u00e2rst\\u0103\",\"text\":\"\\u00cendep\\u0103rtarea cu laser a machiajului permanent este sigur\\u0103 pentru pielea de orice v\\u00e2rst\\u0103. Procedura \\u00eei red\\u0103 culoarea \\u0219i nuan\\u021ba natural\\u0103, moliciunea \\u0219i elasticitatea.\"},{\"MIGX_id\":\"3\",\"number\":\"03\",\"title\":\"F\\u0103r\\u0103 perioad\\u0103 de recuperare\",\"text\":\"Raza laserului ac\\u021bioneaz\\u0103 doar asupra pigmentului, f\\u0103r\\u0103 a afecta pielea. F\\u0103r\\u0103 cruste, cicatrici \\u0219i vindecare \\u00eendelungat\\u0103. Dup\\u0103 procedur\\u0103 sunt necesare doar 1\\u20132 zile de \\u00eengrijire a pielii.\"}]');
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (284, 625, '[{\"MIGX_id\":\"2\",\"title\":\"Laser cu neodim Medicalase Nano-Light 60 XL\",\"image\":\"\\/images\\/inner\\/eq2.png\"},{\"MIGX_id\":\"3\",\"title\":\"Solu\\u021bie Remover\",\"image\":\"images\\/inner\\/eq3.jpg\"},{\"MIGX_id\":\"4\",\"title\":\"Aparat de r\\u0103cire a pielii Face Lift 3 in 1\",\"image\":\"\\/images\\/inner\\/eq-face-lift.webp\"}]');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1625, 'document', 'text/html', 'Laser tattoo removal in Bucharest', 'Laser tattoo removal in Bucharest, eyebrow PMU removal prices', 'Laser removal of tattoos and permanent makeup ✅ Sector 1, Bucharest ➔ we correct tattoos ✓ we remove tattoos of any complexity ➔ certified latest-generation laser', 'laser-tattoo-removal', '', 1, 0, 0, 1080, 0, '', '', 1, 19, 3, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Laser tattoo removal', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'laser-tattoo-removal', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (24, 1625, 'lbar1-min.jpg'),
  (31, 1625, 'Photo gallery <span class=\"gold-word\">– laser removal <br>before and after</br></span>'),
  (34, 1625, 'Laser tattoo removal reviews'),
  (37, 1625, '[{\"MIGX_id\":\"1\",\"questions-title\":\"How long does a laser tattoo removal course take in Bucharest?\",\"questions-text\":\"<p>Laser removal is a course of several sessions. The procedure is done once a month. You can wait longer between sessions, but it is recommended not to do it more often than once every 30 days \\u2014 otherwise the skin doesn\'t have time to recover, which can lead to scars and wounds. The number of sessions is set by the specialist after examining the tattoo and its reaction to the laser beam. It also depends on the size and color of the tattoo. On average, 6\\u20138 sessions are needed.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"How many sessions does eyebrow permanent makeup removal take?\",\"questions-text\":\"<p>The number of sessions depends on several factors: the result you want and the initial condition of the tattoo. If you want to lighten the pigment partially so it can be covered later, or to remove powder brows, 2\\u20133 sessions will be enough. To remove an eyebrow tattoo completely, at least 4\\u20136 sessions are needed.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"How much does tattoo removal cost?\",\"questions-text\":\"<p>The cost of the course depends on the number of sessions and the size of the tattooed area. See the price list.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Which is more effective for eyebrow permanent makeup: laser removal or a cover-up?\",\"questions-text\":\"<p>It all depends on the initial condition of the eyebrow permanent makeup. Most often a cover-up won\'t help you change the color or shape, especially if the tattoo is old or has turned an unnatural shade. In that case a cover-up gives no result and makes your look less natural. Laser removal is the best solution if you want to remove eyebrow permanent makeup partially or completely. After the tattoo is removed, you can get new, beautiful permanent makeup. This can be the most effective option for a pretty, natural look.<\\/p>\"},{\"MIGX_id\":\"5\",\"questions-title\":\"What are the specifics of laser removal?\",\"questions-text\":\"<p>Laser removal uses a special laser device. It generates a beam that breaks the pigment down into particles, which are then eliminated naturally, without any discomfort. During the procedure you feel a slight tingling, but because it is so short, it is painless. Laser removal is considered the most advanced and effective procedure available today. No other alternative guarantees a similar result in terms of effect and safety.<\\/p>\"},{\"MIGX_id\":\"6\",\"questions-title\":\"How is the procedure done, and does it hurt?\",\"questions-text\":\"<p>Before the procedure, the PMU artist cleans the keratinized skin particles from the area where the tattoo will be removed. Then the procedure is performed; you are given protective glasses. Each session takes no more than 10\\u201315 minutes, depending on the area of the tattoo being removed. At the end, the area may be treated with a regenerating, revitalizing cream, depending on how the skin reacts. Pain is minimal, because the beam acts only on the pigment and the skin doesn\'t heat up much during the session, so there is no real pain. However, if your skin is very sensitive, the specialist will use an anesthetic.<\\/p>\"},{\"MIGX_id\":\"7\",\"questions-title\":\"How does the skin heal after the procedure?\",\"questions-text\":\"<p>When the laser is used correctly and set up properly, no special aftercare is needed. It is recommended to protect the treated area from clothing friction and external factors as much as possible. Avoid steaming your skin and exposing it to ultraviolet light.<\\/p>\"},{\"MIGX_id\":\"8\",\"questions-title\":\"How often should the procedure be done?\",\"questions-text\":\"<p>No more than once a month \\u2014 this is exactly the time the skin needs to heal and recover. If you prefer, you can remove the tattoo at longer intervals: once every 2 months or even less often. It is up to the client.<\\/p>\"},{\"MIGX_id\":\"9\",\"questions-title\":\"Do I need to prepare for the procedure?\",\"questions-text\":\"<p>The procedure requires no special preparation. Just avoid injuring your skin and sunbathing.<\\/p>\"},{\"MIGX_id\":\"10\",\"questions-title\":\"When is laser removal not allowed?\",\"questions-text\":\"<p>Laser removal is not recommended if there are wounds, acne or inflammation in the tattoo area. The procedure is contraindicated in diabetes, low blood clotting, while taking iron supplements or corticosteroids, or with varicose veins larger than 0.5 cm in diameter.<\\/p>\"}]'),
  (40, 1625, 'laserbanner1.jpg'),
  (55, 1625, 'Request a <span class=\"gold-word\">free</span> consultation'),
  (56, 1625, 'We will tell you the estimated number of sessions and the cost of the course'),
  (65, 1625, 'Frequently asked questions'),
  (68, 1625, '<p><span> </span></p>'),
  (156, 1625, '[[$table-three-col-bl7]]'),
  (160, 1625, 'Laser tattoo removal'),
  (161, 1625, 'studio LBAR'),
  (162, 1625, 'Remove tattoos for good with up to 98% effectiveness by the end of the course'),
  (163, 1625, 'The highest level of safety'),
  (164, 1625, 'Up to 10 minutes per session'),
  (165, 1625, 'No scars and no side effects'),
  (166, 1625, 'Removal of any type of tattoo and permanent makeup'),
  (272, 1625, 'Request a consultation'),
  (276, 1625, '<span class=\"gold-word\">Dreaming of clear, tattoo-free skin?</span> Laser tattoo removal is the best option'),
  (277, 1625, '<p>There is no more effective and proven method of removing eyebrow permanent makeup and tattoos than the laser. Whatever needs to go — eyebrow permanent makeup, microblading, lip micropigmentation or an old, faded tattoo; a worn-out tattoo or simply one you no longer like — in absolutely every case, permanent makeup and tattoos will be removed. And you won\'t feel any real discomfort: the procedure causes minimal pain. For high sensitivity, an anesthetic gel can be used when removing large tattoos<br />It all goes very easily! Just a few minutes once a month, and after only a few removal sessions you will have beautiful skin with a natural color, without a trace of pigment or ink.</p>'),
  (279, 1625, '<p>The key to a successful procedure is the equipment. To remove the pigment, the PMU artist chooses the most suitable and effective removal option: the laser alone or, in complicated cases, a combination of the laser and remover. It depends on the age, color and intensity of the pigment. The removal methods can overlap and complement each other — but a positive result is guaranteed.</p>'),
  (281, 1625, '/images/inner/ph1.png'),
  (282, 1625, 'Benefits of <span class=\"gold-word\">laser tattoo and permanent makeup removal</span>'),
  (283, 1625, '[{\"MIGX_id\":\"1\",\"number\":\"01\",\"title\":\"No burns, no scars, no marks.\",\"text\":\"Once healed, the skin is perfectly clean, without a single trace, and fully ready for new pigment if needed.\"},{\"MIGX_id\":\"2\",\"number\":\"02\",\"title\":\"Safe for skin of any age\",\"text\":\"Laser removal of permanent makeup is safe for skin of any age. The procedure restores its natural color and tone, softness and elasticity.\"},{\"MIGX_id\":\"3\",\"number\":\"03\",\"title\":\"No recovery period\",\"text\":\"The laser beam acts only on the pigment without harming the skin. No scabs, no scars and no lengthy healing. After the procedure, just 1\\u20132 days of skin care are needed.\"}]'),
  (284, 1625, '[{\"MIGX_id\":\"2\",\"title\":\"Medicalaser Nano-Light 60 XL neodymium laser\",\"image\":\"\\/images\\/inner\\/eq2.png\"},{\"MIGX_id\":\"3\",\"title\":\"Remover solution\",\"image\":\"images\\/inner\\/eq3.jpg\"},{\"MIGX_id\":\"4\",\"title\":\"Face Lift 3 in 1 skin cooling device\",\"image\":\"\\/images\\/inner\\/eq-face-lift.webp\"}]'),
  (285, 1625, 'The equipment we use'),
  (287, 1625, '<p>In most cases we use the neodymium laser. It is a powerful, professional, latest-generation device that removes tattoos and permanent makeup regardless of their depth. With the neodymium laser we successfully remove eyebrow, lip and eyelid permanent makeup as well as black-and-white and color tattoos, with the best possible results.</p>'),
  (288, 1625, 'Our specialists in <span class=\"gold-word\">tattoo and permanent makeup removal</span>'),
  (289, 1625, '[{\"MIGX_id\":\"1\",\"name\":\"Igor\",\"image\":\"\\/images\\/inner\\/s3.png\",\"text\":\"Laser cosmetology specialist. Over 5 years of experience.\"},{\"MIGX_id\":\"2\",\"name\":\"Aliona\",\"image\":\"\\/images\\/inner\\/s2.png\",\"text\":\"Laser cosmetology specialist. Over 5 years of experience.\"},{\"MIGX_id\":\"3\",\"name\":\"Ksenia\",\"image\":\"\\/images\\/inner\\/s1.png\",\"text\":\"Laser cosmetology specialist. Top PMU artist. Over 10 years of experience.\"}]'),
  (294, 1625, '/images/inner/lazxe.png'),
  (300, 1625, 'Laser tattoo and permanent makeup removal <span class=\"gold-word\">prices</span>'),
  (301, 1625, '<p>The number of sessions depends on how deep and how much pigment was injected into the skin. Removal of eyebrow, lip and eye permanent makeup has a fixed price. Lip tattoos are most often removed with Remover solution rather than with the laser. Tattoos are assessed individually; approximate prices are listed below. To get an exact quote, send us a photo on WhatsApp at +40 720 203 105. <span style=\"background-color: #ffcc00;\">The price depends not only on the width and length of the tattoo, but also on its density.</span></p>\r\n<table>\r\n<thead>\r\n<tr class=\"odd\"><th scope=\"col\">\r\n<p><span id=\"docs-internal-guid-7fafb73c-7fff-5a19-14c7-06ab75a3be09\"><span>Procedure</span></span></p>\r\n</th><th scope=\"col\">\r\n<p><span id=\"docs-internal-guid-7873f005-7fff-7a24-8098-1bb8dcde9fc1\"><span>Laser removal, RON</span></span></p>\r\n</th><th scope=\"col\">\r\n<p><span id=\"docs-internal-guid-96dfddb2-7fff-b2c9-2e8a-47deea22f9c5\"><span>Solution removal</span></span>, RON</p>\r\n</th></tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-84b5f16b-7fff-dbc8-8987-c63d8208b895\"><span>Tattoo removal up to 5 cm2</span></span></td>\r\n<td class=\"price\">from 150</td>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-2a453020-7fff-7582-ee8f-1cad8e3b9652\"><span>Tattoo removal 5-15 cm2</span></span></td>\r\n<td class=\"price\">from 250</td>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-d587d851-7fff-913f-d51e-a34e376584be\"><span>Tattoo removal 15-20 cm2</span></span></td>\r\n<td class=\"price\">from 400</td>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-7175e8c9-7fff-bb03-1cf1-bf4422140f9d\"><span>Tattoo removal over 20 cm2</span></span></td>\r\n<td class=\"price\">from 450</td>\r\n<td> </td>\r\n</tr>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-ca2835ae-7fff-e835-84a8-37f7910eeaab\"><span>Eyebrow permanent makeup removal</span></span></td>\r\n<td class=\"price\">300</td>\r\n<td>400</td>\r\n</tr>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-153d1998-7fff-158e-1dd7-7fb551358e9b\"><span>Eye permanent makeup removal</span></span></td>\r\n<td class=\"price\">300</td>\r\n<td>400</td>\r\n</tr>\r\n<tr>\r\n<td><span id=\"docs-internal-guid-dd12304e-7fff-3344-9dbe-f112c701b36f\"><span>Lip permanent makeup removal</span></span></td>\r\n<td class=\"price\">300</td>\r\n<td>400</td>\r\n</tr>\r\n</tbody>\r\n</table>');
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) SELECT 304, 1625, value FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid = 304 AND contentid = 625;
